Certainly! Below is a C++ code snippet that initializes a `std::array` with 176 elements, all set to zero. It then prints the first 10 and last 10 elements of the array.

```cpp
#include <array>
#include <iostream>

int main() {
    // Initialize a std::array with 176 elements, all set to zero
    std::array<int, 176> myArray = {};

    // Print the first 10 elements
    std::cout << "First 10 elements: ";
    for (int i = 0; i < 10; ++i) {
        std::cout << myArray[i] << " ";
    }
    std::cout << std::endl;

    // Print the last 10 elements
    std::cout << "Last 10 elements: ";
    for (int i = 166; i < 176; ++i) {
        std::cout << myArray[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

